using System.Buffers;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

public static class JsonOutput
{
    private static readonly JsonWriterOptions WriterOptions = new JsonWriterOptions
    {
        Indented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    public static byte[] PlanBytes(EngineResult r)
    {
        var buffer = new ArrayBufferWriter<byte>();
        using (var writer = new Utf8JsonWriter(buffer, WriterOptions))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", 1);

            writer.WriteStartArray("items");
            foreach (var item in r.Items)
            {
                writer.WriteStartObject();
                writer.WriteString("original", item.Original);
                writer.WriteString("proposed", item.Proposed);
                writer.WriteString("status", item.Status);
                writer.WriteString("reason", item.Reason);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();

            writer.WriteStartObject("summary");
            writer.WriteNumber("total", r.Summary.Total);
            writer.WriteNumber("ok", r.Summary.Ok);
            writer.WriteNumber("collision", r.Summary.Collision);
            writer.WriteNumber("unchanged", r.Summary.Unchanged);
            writer.WriteNumber("invalid", r.Summary.Invalid);
            writer.WriteEndObject();

            writer.WriteEndObject();
        }
        return buffer.WrittenSpan.ToArray();
    }

    public static byte[] TraceBytes(EngineResult r)
    {
        var buffer = new ArrayBufferWriter<byte>();
        using (var writer = new Utf8JsonWriter(buffer, WriterOptions))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", 1);

            writer.WriteStartArray("files");
            foreach (var file in r.Files)
            {
                writer.WriteStartObject();
                writer.WriteString("original", file.Original);

                writer.WriteStartArray("steps");
                foreach (var step in file.Steps)
                {
                    writer.WriteStartObject();
                    writer.WriteNumber("index", step.Index);
                    writer.WriteString("op", step.Op);
                    writer.WriteString("before", step.Before);
                    writer.WriteString("after", step.After);
                    writer.WriteEndObject();
                }
                writer.WriteEndArray();

                writer.WriteString("proposed", file.Proposed);
                writer.WriteString("status", file.Status);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();

            writer.WriteEndObject();
        }
        return buffer.WrittenSpan.ToArray();
    }

    /// <summary>Creates the parent directory if needed, writes bytes verbatim.</summary>
    public static void WriteFile(string path, byte[] bytes)
    {
        string? dir = Path.GetDirectoryName(path);
        if (!string.IsNullOrEmpty(dir))
        {
            Directory.CreateDirectory(dir);
        }
        File.WriteAllBytes(path, bytes);
    }
}
