using System.ComponentModel;
using System.Text.Json;

namespace BatchRenameStudio.Core.Model;

public abstract class RuleStep
{
    /// <summary>JSON "op" value, e.g. "replace".</summary>
    public abstract string Op { get; }

    /// <summary>
    /// GUI-only. Never serialized. Disabled steps are dropped before the
    /// engine runs, so they never appear in a trace.
    /// </summary>
    [Browsable(false)]
    public bool Enabled { get; set; } = true;

    /// <summary>Mutates state. MUST NOT throw for any input.</summary>
    public abstract void Apply(StepContext ctx, NameState state);

    /// <summary>
    /// Reads this step's own properties from its JSON object.
    /// Missing/invalid members fall back to the documented default.
    /// MUST NOT throw.
    /// </summary>
    public abstract void ReadJson(JsonElement element);

    /// <summary>
    /// Writes this step's own properties. The caller has already written
    /// StartObject and the "op" property.
    /// </summary>
    public abstract void WriteJson(Utf8JsonWriter writer);

    /// <summary>One-line Traditional-Chinese summary for the GUI rule list.</summary>
    public abstract string Describe();
}

