using BatchRenameStudio.Core.Model;

namespace BatchRenameStudio.Core;

/// <summary>
/// Runs the rule chain over a list of file names and produces both the plan
/// and the trace in a single pass, so they can never disagree.
/// </summary>
public static class RenameEngine
{
    public static EngineResult Run(string dir, RuleSet rules)
    {
        var names = FileScanner.Scan(dir, rules.Sort).Select(f => f.Name).ToList();
        return Run(names, rules);
    }

    /// <summary>Same, for a caller that already scanned (GUI reuse).</summary>
    public static EngineResult Run(IReadOnlyList<string> fileNames, RuleSet rules)
    {
        var result = new EngineResult();
        var proposed = new string[fileNames.Count];

        for (int i = 0; i < fileNames.Count; i++)
        {
            string name = fileNames[i];
            var (b, e) = NameRules.Split(name);
            var ctx = new StepContext(i, name, b, e, rules.ApplyTo);
            var state = rules.ApplyTo == ApplyTo.Name
                ? new NameState { Target = b, Ext = e }
                : new NameState { Target = name, Ext = "" };

            var trace = new TraceFile { Original = name };

            for (int k = 0; k < rules.Steps.Count; k++)
            {
                var step = rules.Steps[k];
                string before = state.Target;
                step.Apply(ctx, state);
                trace.Steps.Add(new TraceStep
                {
                    Index = k,
                    Op = step.Op,
                    Before = before,
                    After = state.Target
                });
            }

            string finalName = rules.ApplyTo == ApplyTo.Name
                ? NameRules.Join(state.Target, state.Ext)
                : state.Target;

            proposed[i] = finalName;

            result.Items.Add(new PlanItem { Original = name, Proposed = finalName });
            trace.Proposed = finalName;
            result.Files.Add(trace);
        }

        // Existing-name lookup: case-insensitive name -> index (first occurrence
        // is enough; we only need "does some other index have this name").
        var existingIndex = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < fileNames.Count; i++)
        {
            if (!existingIndex.TryGetValue(fileNames[i], out var list))
            {
                list = new List<int>();
                existingIndex[fileNames[i]] = list;
            }
            list.Add(i);
        }

        // Proposed-name lookup: case-insensitive proposed name -> indices.
        var proposedIndex = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < proposed.Length; i++)
        {
            if (!proposedIndex.TryGetValue(proposed[i], out var list))
            {
                list = new List<int>();
                proposedIndex[proposed[i]] = list;
            }
            list.Add(i);
        }

        var summary = new PlanSummary { Total = fileNames.Count };

        for (int i = 0; i < fileNames.Count; i++)
        {
            string status;
            string reason;

            if (NameRules.IsInvalid(proposed[i], out var invalidReason))
            {
                status = PlanStatus.Invalid;
                reason = invalidReason;
            }
            else if (HasOtherEntry(existingIndex, fileNames[i], i) ||
                     HasOtherEntry(proposedIndex, proposed[i], i))
            {
                status = PlanStatus.Collision;
                reason = HasOtherEntry(existingIndex, fileNames[i], i) ? "與現有檔案衝突" : "與其他項目的結果衝突";
            }
            else if (string.Equals(proposed[i], fileNames[i], StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = "";
            }
            else
            {
                status = PlanStatus.Ok;
                reason = "";
            }

            result.Items[i].Status = status;
            result.Items[i].Reason = reason;
            result.Files[i].Status = status;

            switch (status)
            {
                case PlanStatus.Ok: summary.Ok++; break;
                case PlanStatus.Collision: summary.Collision++; break;
                case PlanStatus.Unchanged: summary.Unchanged++; break;
                case PlanStatus.Invalid: summary.Invalid++; break;
            }
        }

        result.Summary = summary;
        return result;
    }

    private static bool HasOtherEntry(Dictionary<string, List<int>> index, string key, int selfIndex)
    {
        if (!index.TryGetValue(key, out var list)) return false;
        foreach (var j in list)
        {
            if (j != selfIndex) return true;
        }
        return false;
    }
}

