using BatchRenameStudio.Core.Model;

namespace BatchRenameStudio.Core;

/// <summary>
/// Enumerates regular files directly inside a directory (spec rules 1 and 5).
/// </summary>
public static class FileScanner
{
    /// <summary>
    /// Regular files directly inside dir, non-recursive, directories excluded,
    /// sorted per spec rule 5. Throws DirectoryNotFoundException if missing.
    /// </summary>
    public static List<FileInfo> Scan(string dir, SortMode sort)
    {
        var di = new DirectoryInfo(dir);
        if (!di.Exists)
        {
            throw new DirectoryNotFoundException(dir);
        }

        var files = di.GetFiles().ToList();

        Comparison<FileInfo> comparison = sort switch
        {
            SortMode.Created => (a, b) =>
            {
                int c = a.CreationTimeUtc.CompareTo(b.CreationTimeUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            SortMode.Modified => (a, b) =>
            {
                int c = a.LastWriteTimeUtc.CompareTo(b.LastWriteTimeUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            _ => (a, b) => string.CompareOrdinal(a.Name, b.Name)
        };

        files.Sort(comparison);
        return files;
    }
}
