using System.Text.Json;
using BatchRenameStudio.Core;
using BatchRenameStudio.Core.Model;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Implements the two headless contracts:
///   BatchRenameStudio.exe --plan    --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;
///   BatchRenameStudio.exe --explain --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;trace.json&gt;
/// Never renames files and never touches the GUI.
/// </summary>
public static class HeadlessRunner
{
    private const string Usage =
        "usage: BatchRenameStudio.exe --plan|--explain --dir <folder> --rules <rules.json> --out <out.json>";

    public static int Run(string[] args)
    {
        if (args.Length == 0 || (args[0] != "--plan" && args[0] != "--explain"))
        {
            Console.Error.WriteLine(Usage);
            return 2;
        }
        bool isPlan = args[0] == "--plan";

        string? dir = null, rulesPath = null, outPath = null;

        for (int i = 1; i < args.Length; i++)
        {
            string flag = args[i];
            if (flag != "--dir" && flag != "--rules" && flag != "--out")
            {
                Console.Error.WriteLine($"未知參數: {flag}");
                Console.Error.WriteLine(Usage);
                return 2;
            }
            if (i + 1 >= args.Length)
            {
                Console.Error.WriteLine($"缺少 {flag} 的值");
                Console.Error.WriteLine(Usage);
                return 2;
            }
            i++;
            switch (flag)
            {
                case "--dir": dir = args[i]; break;
                case "--rules": rulesPath = args[i]; break;
                case "--out": outPath = args[i]; break;
            }
        }

        if (dir == null || rulesPath == null || outPath == null)
        {
            Console.Error.WriteLine("缺少必要參數 --dir/--rules/--out");
            Console.Error.WriteLine(Usage);
            return 2;
        }

        try
        {
            RuleSet rules;
            try
            {
                rules = RulesJson.Load(rulesPath);
            }
            catch (JsonException ex)
            {
                Console.Error.WriteLine($"規則檔格式錯誤: {ex.Message}");
                return 3;
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                Console.Error.WriteLine($"無法讀取規則檔: {ex.Message}");
                return 3;
            }

            EngineResult result;
            try
            {
                result = RenameEngine.Run(dir, rules);
            }
            catch (DirectoryNotFoundException ex)
            {
                Console.Error.WriteLine($"找不到資料夾: {ex.Message}");
                return 4;
            }

            try
            {
                byte[] bytes = isPlan ? JsonOutput.PlanBytes(result) : JsonOutput.TraceBytes(result);
                JsonOutput.WriteFile(outPath, bytes);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                Console.Error.WriteLine($"無法寫入輸出檔: {ex.Message}");
                return 5;
            }

            if (isPlan)
            {
                var s = result.Summary;
                Console.Out.WriteLine(
                    $"plan: total={s.Total} ok={s.Ok} collision={s.Collision} unchanged={s.Unchanged} invalid={s.Invalid} -> {outPath}");
            }
            else
            {
                int stepCount = result.Files.Sum(f => f.Steps.Count);
                Console.Out.WriteLine($"explain: files={result.Files.Count} steps={stepCount} -> {outPath}");
            }
            Console.Out.Flush();

            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine(ex.Message);
            return 1;
        }
    }
}

