using System.Buffers;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using BatchRenameStudio.Core.Model;

namespace BatchRenameStudio.Core;

/// <summary>
/// Parses and serializes the rules JSON document used both by the GUI's
/// save/load and by the CLI's --rules flag.
/// </summary>
public static class RulesJson
{
    private static readonly JsonWriterOptions WriterOptions = new JsonWriterOptions
    {
        Indented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    /// <summary>Throws JsonException on malformed JSON.</summary>
    public static RuleSet Parse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        var rules = new RuleSet
        {
            ApplyTo = ParseApplyTo(root),
            Sort = ParseSort(root)
        };

        if (root.ValueKind == JsonValueKind.Object &&
            root.TryGetProperty("steps", out var steps) &&
            steps.ValueKind == JsonValueKind.Array)
        {
            foreach (var element in steps.EnumerateArray())
            {
                if (element.ValueKind != JsonValueKind.Object) continue;

                string op = "";
                if (element.TryGetProperty("op", out var opEl) && opEl.ValueKind == JsonValueKind.String)
                {
                    op = opEl.GetString() ?? "";
                }

                var s = StepFactory.Create(op);
                s.ReadJson(element);
                rules.Steps.Add(s);
            }
        }

        return rules;
    }

    public static RuleSet Load(string path)
    {
        return Parse(File.ReadAllText(path, new UTF8Encoding(false)));
    }

    public static string Serialize(RuleSet rules)
    {
        var buffer = new ArrayBufferWriter<byte>();
        using (var writer = new Utf8JsonWriter(buffer, WriterOptions))
        {
            WriteRules(writer, rules);
        }
        return Encoding.UTF8.GetString(buffer.WrittenSpan);
    }

    public static void Save(string path, RuleSet rules)
    {
        var buffer = new ArrayBufferWriter<byte>();
        using (var writer = new Utf8JsonWriter(buffer, WriterOptions))
        {
            WriteRules(writer, rules);
        }
        JsonOutput.WriteFile(path, buffer.WrittenSpan.ToArray());
    }

    private static void WriteRules(Utf8JsonWriter writer, RuleSet rules)
    {
        writer.WriteStartObject();
        writer.WriteString("applyTo", ApplyToToJson(rules.ApplyTo));
        writer.WriteString("sort", SortToJson(rules.Sort));

        writer.WriteStartArray("steps");
        foreach (var step in rules.Steps)
        {
            writer.WriteStartObject();
            writer.WriteString("op", step.Op);
            step.WriteJson(writer);
            writer.WriteEndObject();
        }
        writer.WriteEndArray();

        writer.WriteEndObject();
    }

    private static ApplyTo ParseApplyTo(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Object &&
            root.TryGetProperty("applyTo", out var v) && v.ValueKind == JsonValueKind.String)
        {
            var s = v.GetString();
            if (string.Equals(s, "name", StringComparison.OrdinalIgnoreCase)) return ApplyTo.Name;
            if (string.Equals(s, "nameAndExtension", StringComparison.OrdinalIgnoreCase)) return ApplyTo.NameAndExtension;
        }
        return ApplyTo.Name;
    }

    private static SortMode ParseSort(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Object &&
            root.TryGetProperty("sort", out var v) && v.ValueKind == JsonValueKind.String)
        {
            var s = v.GetString();
            if (string.Equals(s, "name", StringComparison.OrdinalIgnoreCase)) return SortMode.Name;
            if (string.Equals(s, "created", StringComparison.OrdinalIgnoreCase)) return SortMode.Created;
            if (string.Equals(s, "modified", StringComparison.OrdinalIgnoreCase)) return SortMode.Modified;

