/// <summary>
/// Renames "to" back to "from" for every entry, processing entries in
/// reverse order using the same two-phase temp-rename strategy as Apply.
/// </summary>
public static ApplyResult Undo(JournalData data)
{
    var result = new ApplyResult();
    string dir = data.Directory;

    var reversed = new List<JournalEntry>(data.Entries);
    reversed.Reverse();

    var eligible = new List<JournalEntry>();
    foreach (var entry in reversed)
    {
        bool toExists = File.Exists(Path.Combine(dir, entry.To));
        bool fromExists = File.Exists(Path.Combine(dir, entry.From));
        if (!toExists || fromExists)
        {
            // Skip: nothing to undo, or the original name is already taken.
            result.Outcomes.Add(new RenameOutcome(entry.To, entry.From, false,
                !toExists ? "來源檔案不存在，略過" : "目標檔名已存在，略過"));
            continue;
        }
        eligible.Add(entry);
    }

    // Phase 1: move each "to" to a unique temp name.
    var tempNameByEntry = new Dictionary<JournalEntry, string>();
    var phase1Failed = new HashSet<JournalEntry>();
    int tempCounter = 0;

    foreach (var entry in eligible)
    {
        string tempName;
        string tempPath;
        do
        {
            tempCounter++;
            tempName = entry.To + ".brs-tmp-" + tempCounter;
            tempPath = Path.Combine(dir, tempName);
        } while (File.Exists(tempPath) || Directory.Exists(tempPath));

        try
