// Lead's acceptance probe for the GUI-only code paths (RenameExecutor, UndoJournal).
// Lives outside the product tree; compiles the product's Core sources directly.
using BatchRenameStudio.Core;

int pass = 0, fail = 0;
void Check(bool cond, string msg)
{
    if (cond) { pass++; }
    else { fail++; Console.WriteLine("  FAIL: " + msg); }
}

string Names(string dir)
{
    var n = new DirectoryInfo(dir).GetFiles().Select(f => f.Name).ToList();
    n.Sort(StringComparer.Ordinal);
    return string.Join(",", n);
}

string MakeDir(string tag)
{
    string d = Path.Combine(Path.GetTempPath(), "brs-exec-" + tag);
    if (Directory.Exists(d)) Directory.Delete(d, true);
    Directory.CreateDirectory(d);
    return d;
}

void Touch(string dir, string name) =>
    File.WriteAllText(Path.Combine(dir, name), name);

// ---------- scenario 1: apply then undo, including case-only renames ----------
{
    string dir = MakeDir("1");
    Touch(dir, "a.txt"); Touch(dir, "b.txt"); Touch(dir, "keep.txt");

    var rules = RulesJson.Parse("{\"applyTo\":\"name\",\"sort\":\"name\",\"steps\":[{\"op\":\"case\",\"mode\":\"upper\"}]}");
    var plan = RenameEngine.Run(dir, rules);
    Check(plan.Summary.Ok == 3, $"s1 expected 3 ok, got {plan.Summary.Ok}");

    var applied = RenameExecutor.Apply(dir, plan.Items);
    Check(applied.SuccessCount == 3, $"s1 apply success={applied.SuccessCount} want 3");
    Check(applied.FailureCount == 0, $"s1 apply failures={applied.FailureCount} want 0");
    Check(Names(dir) == "A.txt,B.txt,KEEP.txt", $"s1 after apply: {Names(dir)}");
    Check(applied.JournalPath != null && File.Exists(applied.JournalPath!), "s1 journal file written");
    Check(File.ReadAllText(Path.Combine(dir, "A.txt")) == "a.txt", "s1 content followed the rename");

    Check(UndoJournal.TryLoadLatest(out var data), "s1 TryLoadLatest");
    Check(string.Equals(data.Directory, dir, StringComparison.OrdinalIgnoreCase), $"s1 journal dir = {data.Directory}");
    Check(data.Entries.Count == 3, $"s1 journal entries={data.Entries.Count} want 3");

    var undone = UndoJournal.Undo(data);
    Check(undone.SuccessCount == 3, $"s1 undo success={undone.SuccessCount} want 3");
    Check(Names(dir) == "a.txt,b.txt,keep.txt", $"s1 after undo: {Names(dir)}");
    if (applied.JournalPath != null) UndoJournal.Delete(applied.JournalPath);
    Directory.Delete(dir, true);
}

// ---------- scenario 2: collisions must be skipped, disk untouched ----------
{
    string dir = MakeDir("2");
    Touch(dir, "x.txt"); Touch(dir, "y.txt");
    string before = Names(dir);

    var rules = RulesJson.Parse("{\"applyTo\":\"name\",\"sort\":\"name\",\"steps\":[{\"op\":\"replace\",\"find\":\"y\",\"replaceWith\":\"x\"}]}");
    var plan = RenameEngine.Run(dir, rules);
    Check(plan.Summary.Collision == 2, $"s2 collisions={plan.Summary.Collision} want 2");

    var applied = RenameExecutor.Apply(dir, plan.Items);
    Check(applied.SuccessCount == 0, $"s2 success={applied.SuccessCount} want 0");
    Check(applied.JournalPath == null, "s2 no journal for a no-op apply");
    Check(Names(dir) == before, $"s2 disk changed: {Names(dir)}");
    Directory.Delete(dir, true);
}

// ---------- scenario 3: invalid names must be skipped ----------
{
    string dir = MakeDir("3");
    Touch(dir, "p.txt"); Touch(dir, "q.txt");
    string before = Names(dir);

    var rules = RulesJson.Parse("{\"applyTo\":\"name\",\"sort\":\"name\",\"steps\":[{\"op\":\"template\",\"format\":\"CON\"}]}");
    var plan = RenameEngine.Run(dir, rules);
    Check(plan.Summary.Invalid == 2, $"s3 invalid={plan.Summary.Invalid} want 2");

    var applied = RenameExecutor.Apply(dir, plan.Items);
    Check(applied.SuccessCount == 0, $"s3 success={applied.SuccessCount} want 0");
    Check(Names(dir) == before, $"s3 disk changed: {Names(dir)}");
    Directory.Delete(dir, true);
}

// ---------- scenario 4: partial batch — only ok items move ----------
{
    string dir = MakeDir("4");
    Touch(dir, "m1.txt"); Touch(dir, "m2.txt"); Touch(dir, "same.txt");
    // sequence renames m1/m2; "same.txt" is left as-is by an unchanged-producing rule set
    var rules = RulesJson.Parse("{\"applyTo\":\"name\",\"sort\":\"name\",\"steps\":[{\"op\":\"replace\",\"find\":\"m\",\"replaceWith\":\"z\"}]}");
    var plan = RenameEngine.Run(dir, rules);
    Check(plan.Summary.Ok == 2 && plan.Summary.Unchanged == 1,
        $"s4 ok={plan.Summary.Ok} unchanged={plan.Summary.Unchanged} want 2/1");

    var applied = RenameExecutor.Apply(dir, plan.Items);
    Check(applied.SuccessCount == 2, $"s4 success={applied.SuccessCount} want 2");
    Check(applied.Outcomes.Count == 2, $"s4 outcomes={applied.Outcomes.Count} want 2 (skips are not failures)");
    Check(Names(dir) == "same.txt,z1.txt,z2.txt", $"s4 after apply: {Names(dir)}");

    Check(UndoJournal.TryLoadLatest(out var d4), "s4 TryLoadLatest");
    var undone = UndoJournal.Undo(d4);
    Check(undone.SuccessCount == 2, $"s4 undo success={undone.SuccessCount} want 2");
    Check(Names(dir) == "m1.txt,m2.txt,same.txt", $"s4 after undo: {Names(dir)}");
    if (applied.JournalPath != null) UndoJournal.Delete(applied.JournalPath);
    Directory.Delete(dir, true);
}

// ---------- scenario 5: undo must not clobber a name that came back ----------
{
    string dir = MakeDir("5");
    Touch(dir, "u.txt");
    var rules = RulesJson.Parse("{\"applyTo\":\"name\",\"sort\":\"name\",\"steps\":[{\"op\":\"insert\",\"text\":\"_v2\",\"position\":\"suffix\"}]}");
    var plan = RenameEngine.Run(dir, rules);
    var applied = RenameExecutor.Apply(dir, plan.Items);
    Check(Names(dir) == "u_v2.txt", $"s5 after apply: {Names(dir)}");

    // someone recreates the original name before undoing
    Touch(dir, "u.txt");
    Check(UndoJournal.TryLoadLatest(out var d5), "s5 TryLoadLatest");
    var undone = UndoJournal.Undo(d5);
    Check(undone.SuccessCount == 0, $"s5 undo must skip, success={undone.SuccessCount} want 0");
    Check(Names(dir) == "u.txt,u_v2.txt", $"s5 both files must survive: {Names(dir)}");
    Check(File.ReadAllText(Path.Combine(dir, "u_v2.txt")) == "u.txt", "s5 renamed file's content intact");
    if (applied.JournalPath != null) UndoJournal.Delete(applied.JournalPath);
    Directory.Delete(dir, true);
}

Console.WriteLine($"EXEC PROBE PASS={pass} FAIL={fail}");
return fail == 0 ? 0 : 1;

